def find_idempotent_k(n, f):
    def apply_function(func, x):
        return func[x - 1]

    def is_idempotent(func):
        for i in range(1, n + 1):
            if apply_function(func, apply_function(func, i)) != apply_function(func, i):
                return False
        return True

    k = 1
    current_func = f[:]
    while not is_idempotent(current_func):
        k += 1
        next_func = [apply_function(current_func, x) for x in range(1, n + 1)]
        current_func = next_func

    return k

n = int(input())
f = list(map(int, input().split()))
print(find_idempotent_k(n, f))
